CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE tenants(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE departments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, description TEXT, UNIQUE(tenant_id,name));
CREATE TABLE business_processes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), department_id UUID REFERENCES departments(id), name TEXT NOT NULL, description TEXT, systems JSONB NOT NULL DEFAULT '[]', inputs JSONB NOT NULL DEFAULT '[]', outputs JSONB NOT NULL DEFAULT '[]', sensitivity TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE research_sources(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), canonical_url TEXT NOT NULL, source_type TEXT NOT NULL, publisher TEXT, title TEXT, published_at TIMESTAMPTZ, retrieved_at TIMESTAMPTZ NOT NULL DEFAULT now(), content_hash TEXT, license TEXT, trust_class TEXT NOT NULL DEFAULT 'C');
CREATE TABLE research_findings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), source_id UUID REFERENCES research_sources(id), claim TEXT NOT NULL, summary TEXT, evidence_excerpt TEXT, confidence NUMERIC(4,3), verification_status TEXT NOT NULL DEFAULT 'unverified', embedding VECTOR(1536));
CREATE TABLE automation_opportunities(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), department_id UUID REFERENCES departments(id), process_id UUID REFERENCES business_processes(id), title TEXT NOT NULL, problem_statement TEXT NOT NULL, proposed_outcome TEXT, feasibility_score NUMERIC(5,2), impact_score NUMERIC(5,2), complexity_score NUMERIC(5,2), confidence NUMERIC(4,3), impact_estimate JSONB NOT NULL DEFAULT '{}', evidence_refs JSONB NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'discovered');
CREATE TABLE capabilities(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), provider TEXT NOT NULL, capability_type TEXT NOT NULL, name TEXT NOT NULL, version TEXT, category TEXT, platform_version_range TEXT, schema JSONB NOT NULL DEFAULT '{}', credential_schema JSONB NOT NULL DEFAULT '{}', docs_url TEXT, source_ref TEXT, license TEXT, risk_level TEXT NOT NULL DEFAULT 'medium', verified_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE agent_tasks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), agent_id TEXT NOT NULL, objective TEXT NOT NULL, input_refs JSONB NOT NULL DEFAULT '[]', output JSONB, status TEXT NOT NULL DEFAULT 'queued', correlation_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE workflow_projects(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), requester_id TEXT NOT NULL, title TEXT NOT NULL, request JSONB NOT NULL, specification JSONB, status TEXT NOT NULL DEFAULT 'requested');
CREATE TABLE workflow_versions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES workflow_projects(id), version INTEGER NOT NULL, target_platform_version TEXT NOT NULL, workflow_json JSONB NOT NULL, configuration_manifest JSONB NOT NULL DEFAULT '{}', validation_report JSONB NOT NULL DEFAULT '{}', artifact_hash TEXT NOT NULL, UNIQUE(project_id,version));
CREATE TABLE approvals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), resource_type TEXT NOT NULL, resource_id UUID NOT NULL, requested_by TEXT NOT NULL, decided_by TEXT, decision TEXT NOT NULL DEFAULT 'pending', rationale TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), decided_at TIMESTAMPTZ);
CREATE TABLE execution_metrics(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), workflow_project_id UUID REFERENCES workflow_projects(id), external_execution_id TEXT, status TEXT NOT NULL, duration_ms BIGINT, estimated_cost NUMERIC(12,4), business_metrics JSONB NOT NULL DEFAULT '{}', occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), actor_type TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, resource_type TEXT, resource_id TEXT, decision TEXT, metadata JSONB NOT NULL DEFAULT '{}', occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
